// Helper: create a rounded rectangle shape geometry
function createRoundedRectGeometry(width, height, radius, segs = 12) {
  const shape = new Shape();
  const w = width * 0.5;
  const h = height * 0.5;
  const r = Math.min(radius, w, h);

  shape.moveTo(-w + r, -h);
  shape.lineTo(w - r, -h);
  shape.quadraticCurveTo(w, -h, w, -h + r);
  shape.lineTo(w, h - r);
  shape.quadraticCurveTo(w, h, w - r, h);
  shape.lineTo(-w + r, h);
  shape.quadraticCurveTo(-w, h, -w, h - r);
  shape.lineTo(-w, -h + r);
  shape.quadraticCurveTo(-w, -h, -w + r, -h);

  return new ShapeGeometry(shape, segs);
}

