// Helper: create a vertical gradient material (two colours mixed by UV.y)
function createVerticalGradientMaterial(colorTop, colorBottom, useEmissive = false) {
  const cTop = new Color(colorTop);
  const cBottom = new Color(colorBottom);
  const uvNode = uv();
  const grad = mix(vec3(cBottom.r, cBottom.g, cBottom.b), vec3(cTop.r, cTop.g, cTop.b), uvNode.y);

  const mat = useEmissive
    ? new MeshStandardNodeMaterial({ colorNode: grad, side: 2, emissiveNode: grad, emissiveIntensity: 1.5 })
    : new MeshBasicNodeMaterial({ colorNode: grad, side: 2 });
  return mat;
}

