// Helper: create a border material (detect UV proximity to edge)
function createCardBodyMaterial(bodyColor, borderColor, borderThickness, radius) {
  const uvNode = uv();
  const aspect = 2.4 / 3.2; // width / height

  // Map UV to [-1,1] range
  const x = sub(mul(uvNode.x, 2), 1);
  const y = sub(mul(uvNode.y, 2), 1);

  // Rounded rect distance (simplified)
  const rx = mul(sub(abs(x), 1 - radius / 1.2), 1.2 / radius);
  const ry = mul(sub(abs(y), 1 - radius / 1.6), 1.6 / radius);
  const d = length(max(vec3(rx, ry, 0), 0));
  // But we'll approximate border with a step of uv coordinates from edges.

  // Easier: compute distance from edge in UV space
  const borderUV = 0.5 * borderThickness / 2.4; // relative to width
  const edgeX = step(1 - borderUV, uvNode.x) + step(uvNode.x, borderUV);
  const edgeY = step(1 - borderUV * aspect, uvNode.y) + step(uvNode.y, borderUV * aspect);
  const isBorder = clamp(add(edgeX, edgeY), 0, 1);

  const bodyCol = new Color(bodyColor);
  const borderCol = new Color(borderColor);
  const finalColor = mix(vec3(bodyCol.r, bodyCol.g, bodyCol.b), vec3(borderCol.r, borderCol.g, borderCol.b), isBorder);

  return new MeshBasicNodeMaterial({ colorNode: finalColor, side: 2 });
}

