// Main createNode
export default function createNode(config, ctx) {
  const group = new Group();

  // --- Backdrop plane (7x6 at z=-2.5) with gradient stops ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = createVerticalGradientMaterial('#ff4450', '#c1121f');
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // --- Card group (holds card body, header, contents, CTA) ---
  const cardGroup = new Group();
  cardGroup.scale.set(1.04, 1.04, 1.04); // initial overshoot
  group.add(cardGroup);

  // Card body (rounded rect)
  const bodyGeometry = createRoundedRectGeometry(2.4, 3.2, 0.06);
  const bodyMaterial = createCardBodyMaterial('#16161d', '#2a2a33', 0.006, 0.06);
  const bodyMesh = new Mesh(bodyGeometry, bodyMaterial);
  cardGroup.add(bodyMesh);

  // Header strip (top edge, 2.4 x 0.08)
  const headerGeo = new PlaneGeometry(2.4, 0.08);
  const headerMat = new MeshPhysicalNodeMaterial({
    color: '#e8ecf2',
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    anisotropy: 0.6,
    side: 2
  });
  const headerMesh = new Mesh(headerGeo, headerMat);
  headerMesh.position.y = 1.6 - 0.04; // top edge center
  cardGroup.add(headerMesh);

  // --- Text layout ---
  const { textContent } = config;
  const items = textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Utility to create text and add to card
  function addText(text, opts, posY) {
    const textObj = ctx.fontAtlas.createText(text, opts);
    textObj.position.set(0, posY, 0.01); // slightly forward
    cardGroup.add(textObj);
    return textObj;
  }

  // Define positions based on vertical rhythm:
  // Card interior padding 0.5 from top => top of interior y = 1.6 - 0.5 = 1.1
  // Tier name at y ~ 1.1 - (fontSize/2)? We'll offset by half line height approx
  const baseY = 1.1;
  let currentY = baseY;

  // "ATELIER RESERVE" (tier-name)
  if (items[0]) {
    currentY -= (items[0].typography?.fontSize ?? 20) * 0.001; // approximate font height in scene units
    addText(items[0].text, { fontSize: items[0].typography?.fontSize ?? 20, color: '#e8ecf2', align: 'center', letterSpacingPx: (items[0].typography?.letterSpacing ?? 0.08) * 20 }, currentY);
    currentY -= 0.12; // gap after tier name
  }

  // "$480" (price)
  if (items[1]) {
    currentY -= (items[1].typography?.fontSize ?? 62) * 0.001;
    addText(items[1].text, { fontSize: items[1].typography?.fontSize ?? 62, color: '#e8ecf2', align: 'center', letterSpacingPx: (items[1].typography?.letterSpacing ?? -0.01) * 62 }, currentY);
    currentY -= 0.1;
  }

  // "PER MONTH, BILLED ANNUALLY" (caption) placed on same baseline as price? Spec says "on its baseline". We'll put slightly below.
  if (items[2]) {
    currentY -= (items[2].typography?.fontSize ?? 9) * 0.001;
    addText(items[2].text, { fontSize: items[2].typography?.fontSize ?? 9, color: '#e8ecf2', align: 'center', letterSpacingPx: (items[2].typography?.letterSpacing ?? 0.12) * 9 }, currentY);
    currentY -= 0.5; // 0.5-unit gap after price+caption
  }

  // Four features + hairline separators (we'll simulate hairlines with thin planes)
  const featureStartY = currentY;
  const featureHeight = 0.375;
  const featureGap = 0.006;
  const features = items.slice(3, 7);

  features.forEach((feat, idx) => {
    const fY = featureStartY - idx * (featureHeight + featureGap) - featureHeight * 0.5;
    // Hairline: thin horizontal line above each feature (except first?)
    if (idx > 0) {
      const lineGeo = new PlaneGeometry(2.0, 0.006);
      const lineMat = new MeshBasicNodeMaterial({ color: '#23232b' });
      const line = new Mesh(lineGeo, lineMat);
      line.position.y = fY + featureHeight * 0.5 + 0.003;
      cardGroup.add(line);
    }
    // Feature text
    const featObj = ctx.fontAtlas.createText(feat.text, {
      fontSize: feat.typography?.fontSize ?? 13,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: (feat.typography?.letterSpacing ?? 0) * 13
    });
    featObj.position.set(0, fY, 0.01);
    featObj.userData.isFeature = true; // for stagger
    cardGroup.add(featObj);
  });

  // --- CTA button row ---
  const ctaY = -1.6 + 0.5 + 0.18; // 0.5 units above bottom, half height (0.36/2)
  const ctaGeo = new PlaneGeometry(1.4, 0.36);
  const ctaMat = new MeshStandardNodeMaterial({
    colorNode: uv().y.map((y) => {
      const cTop = new Color('#ff4450');
      const cBottom = new Color('#c1121f');
      return mix(vec3(cBottom.r, cBottom.g, cBottom.b), vec3(cTop.r, cTop.g, cTop.b), y);
    }),
    emissiveNode: vec3(1, 0.165, 0.22), // #ff2a38
    emissiveIntensity: 1.5,
    side: 2
  });
  const ctaMesh = new Mesh(ctaGeo, ctaMat);
  ctaMesh.position.set(0, ctaY, 0.005);
  cardGroup.add(ctaMesh);

  // CTA label
  if (items[7]) {
    const ctaText = ctx.fontAtlas.createText(items[7].text, {
      fontSize: items[7].typography?.fontSize ?? 13,
      color: '#16161d',
      align: 'center',
      letterSpacingPx: (items[7].typography?.letterSpacing ?? 0.08) * 13
    });
    ctaText.position.set(0, ctaY, 0.02);
    cardGroup.add(ctaText);
    // store reference for hover/press
    ctaMesh.userData.ctaText = ctaText;
  }

  // --- Lights ---
  // Key light from upper-left (moves during settle)
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(-2, 3, 4);
  cardGroup.add(keyLight);
  // Rim light from lower-right (carries accent hue)
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(2, -1, 3);
  cardGroup.add(rimLight);
  // Additional fill
  const fillLight = new DirectionalLight(0xffffff, 0.3);
  fillLight.position.set(0, 0, 5);
  cardGroup.add(fillLight);

  // Ambient is provided by scene, but we add small local ambient for safety
  const ambLight = new AmbientLight(0xffffff, 0.2);
  cardGroup.add(ambLight);

  // --- Animations ---
  const timelines = [];

  // 1. Weighted-settle scale
  const settleTl = gsap.timeline({ delay: 0.2 });
  settleTl.to(cardGroup.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: true
  });
  timelines.push(settleTl);

  // 2. Key light movement during settle (drag specular band)
  const lightTl = gsap.timeline({ delay: 0.2 });
  lightTl.to(keyLight.position, {
    x: -1.5, y: 2.5, z: 3.5,
    duration: 0.9,
    ease: 'power4.out'
  }, 0);
  timelines.push(lightTl);

  // 3. Feature stagger fade-up
  const featureObjects = cardGroup.children.filter(c => c.userData && c.userData.isFeature);
  const staggerTl = gsap.timeline({ delay: 1.1 });
  featureObjects.forEach((obj, i) => {
    // Set initial state
    obj.material && obj.material.opacity !== undefined ? obj.material.opacity = 0 : obj.traverse(child => { if (child.isMesh) child.material.opacity = 0; });
    obj.position.y += 0.2; // offset down
    staggerTl.to(obj.position, {
      y: obj.position.y - 0.2,
      duration: 0.5,
      ease: 'power2.out'
    }, `-=0.5${i * 0.08}`);
    staggerTl.to(obj, {
      duration: 0.5,
      opacity: 1,
      ease: 'power2.out'
    }, `-=0.5${i * 0.08}`);
  });
  timelines.push(staggerTl);

  // --- CTA press interaction ---
  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(ctaMesh.scale, {
    x: 0.97, y: 0.97, z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)'
  }).to(ctaMesh.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.12,
    ease: 'power2.out'
  });

  // Attach click handler
  group.userData.handlers = {
    click: (event) => {
      // Check if clicked object is the CTA or its text
      let target = event.object;
      while (target.parent && !target.isMesh) target = target.parent;
      if (target === ctaMesh || target === ctaMesh.userData.ctaText) {
        pressTl.restart();
        // Optionally emit an event
        ctx.emit('navigate', { to: 'pricing' }); // placeholder
      }
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    pressTl.kill();
    // Dispose geometries and materials
    bodyGeometry.dispose();
    bodyMaterial.dispose();
    headerGeo.dispose();
    headerMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    ctaGeo.dispose();
    ctaMat.dispose();
    // Lights are added to group, no need to dispose
    // Remove event listeners? Not needed.
  };

  return group;
}
